// Command genhttpwriter regenerates the checked-in facade writers of the
// observe package. Run it from the repository root:
//
//	go run ./internal/observe/internal/genhttpwriter
//
// The output is deterministic: the same generator version always produces
// byte-identical files. Normal tests compare the generated file against fresh
// temporary output and never regenerate in place.
package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// facadeBits are the six capability bits in fixed order: F=Flusher,
// H=Hijacker, P=Pusher, C=CloseNotifier, R=ReaderFrom, S=StringWriter.
var facadeBits = []struct {
	bit       uint8
	method    string
	signature string
	body      string
}{
	{1 << 0, "Flush", "()", "w.httpOwner.flush()"},
	{1 << 1, "Hijack", "() (net.Conn, *bufio.ReadWriter, error)", "return w.httpOwner.hijack()"},
	{1 << 2, "Push", "(target string, options *http.PushOptions) error", "return w.httpOwner.push(target, options)"},
	{1 << 3, "CloseNotify", "() <-chan bool", "return w.httpOwner.closeNotify()"},
	{1 << 4, "ReadFrom", "(r io.Reader) (int64, error)", "return w.httpOwner.readFrom(r)"},
	{1 << 5, "WriteString", "(s string) (int, error)", "return w.httpOwner.writeString(s)"},
}

func main() {
	out := flag.String("out", filepath.Join("internal", "observe", "httpwriter_facades_generated.go"), "output file path")
	flag.Parse()

	var b strings.Builder
	b.WriteString(`// Code generated by internal/observe/internal/genhttpwriter. DO NOT EDIT.
// Regenerate with: go run ./internal/observe/internal/genhttpwriter

package observe

import (
	"bufio"
	"io"
	"net"
	"net/http"
)

// The 64 concrete facade types preserve both presence and absence of every
// optional response capability of the underlying writer. Each facade embeds
// its owner by value, so claiming a request allocates exactly one facade.
// Methods appear only where the underlying writer supports the capability:
// a facade without the bit must not satisfy the interface.

`)

	for mask := range 64 {
		name := fmt.Sprintf("httpFacade%06b", mask)
		b.WriteString(fmt.Sprintf("type %s struct {\n\thttpOwner\n}\n\n", name))
		b.WriteString(fmt.Sprintf("func (w *%s) Header() http.Header { return w.httpOwner.header() }\n", name))
		b.WriteString(fmt.Sprintf("func (w *%s) Write(p []byte) (int, error) { return w.httpOwner.write(p) }\n", name))
		b.WriteString(fmt.Sprintf("func (w *%s) WriteHeader(status int) { w.httpOwner.writeHeader(status) }\n", name))
		b.WriteString(fmt.Sprintf("func (w *%s) completionOwner() *httpOwner { return &w.httpOwner }\n", name))
		b.WriteString(fmt.Sprintf("func (w *%s) Unwrap() http.ResponseWriter { return w.httpOwner.writer }\n\n", name))
		for _, bit := range facadeBits {
			if uint8(mask)&bit.bit == 0 {
				continue
			}
			b.WriteString(fmt.Sprintf("func (w *%s) %s%s { %s }\n", name, bit.method, bit.signature, bit.body))
		}
		b.WriteString("\n")
	}

	b.WriteString(`// newHTTPFacadeWriter allocates the single concrete facade selected by the
// probed capability mask and initializes its embedded owner in place.
func newHTTPFacadeWriter(state httpOwnerInit, mask uint8) (http.ResponseWriter, *httpOwner) {
	switch mask {
`)

	for mask := range 64 {
		name := fmt.Sprintf("httpFacade%06b", mask)
		b.WriteString(fmt.Sprintf("\tcase %d:\n", mask))
		b.WriteString(fmt.Sprintf("\t\tvar facade %s\n", name))
		b.WriteString("\t\tfacade.httpOwner.init(state)\n")
		b.WriteString("\t\treturn &facade, &facade.httpOwner\n")
	}

	b.WriteString(`	default:
		panic("observe: capability mask exceeds six bits")
	}
}
`)

	if err := os.WriteFile(*out, []byte(b.String()), 0o644); err != nil {
		fmt.Fprintf(os.Stderr, "genhttpwriter: %v\n", err)
		os.Exit(1)
	}
}
